74		}
75	
76		cases := []struct {
77			name   string
78			mutate func(*PolicySpec)
79		}{
80			{"negative threshold", func(p *PolicySpec) { p.ApprovalThreshold = -1 }},
81			{"threshold exceeds per-request", func(p *PolicySpec) { p.ApprovalThreshold = 31 }},
82			{"zero wait when enabled", func(p *PolicySpec) { p.ApprovalWait = 0 }},
