121		if req.State != RequestPendingApproval {
122			t.Fatalf("state = %v, want pending approval", req.State)
123		}
124		// 等待期限 = min(提交+1分钟, 策略结束, 会话到期) = 提交+1分钟。
125		wantDeadline := c.t.Add(time.Minute)
126		if !req.WaitDeadline.Equal(wantDeadline) {
127			t.Fatalf("wait deadline = %v, want %v", req.WaitDeadline, wantDeadline)
128		}
129		if req.DecidedAt != (time.Time{}) || req.ApproverAccountID != "" || req.RejectReason != "" {
130			t.Fatalf("pending request should have no decision yet: %+v", req)
131		}
132	
133		// 待审批不冻结余额、不占用共享累计额度。
134		bal, _ := w.Balance("payer")
135		if bal != (Balances{Available: 100, Reserved: 0}) {
