685			}
686			if req.DecidedAt.IsZero() {
687				t.Fatalf("%s decision time missing", rid)
688			}
689		}
690		// 余额：待审批未冻结，两笔预留共 15。
691		bal, _ := w.Balance("payer")
692		if bal != (Balances{Available: 85, Reserved: 15}) {
693			t.Fatalf("balance = %+v, want {85 15}", bal)
694		}
695		// 账本含两笔拒绝留痕。
696		rejections := 0
697		for _, e := range w.Ledger() {
698			if e.Kind == LedgerRejection && e.RequestID != "" {
699				rejections++
700			}
701		}
702		if rejections != 2 {
703			t.Fatalf("rejection entries = %d, want 2", rejections)
704		}
705	
706		// 已预留请求：会话吊销后仍可结算。
