713		}
714		// r3 结算扣除 8（不退回），r4 取消退回 7：余额 = 100 - 8 = 92。
715		bal, _ = w.Balance("payer")
716		if bal != (Balances{Available: 92, Reserved: 0}) {
717			t.Fatalf("balance = %+v, want {92 0}", bal)
718		}
719	}
