	save(multiTimeoutPolicy(c, "pb", 30*time.Second))
	save(multiTimeoutPolicy(c, "pc", 20*time.Second))
	ap := multiTimeoutPolicy(c, "pd", 10*time.Second)
	ap.ApprovalThreshold = 10
	ap.ApprovalWait = 2 * time.Hour
